<?php
declare(strict_types=1);
require dirname(__DIR__).'/bootstrap.php';require dirname(__DIR__,2).'/app/autoload.php';
use FMonitor2\InstallationProcess\JobsSchemaMigration;use FMonitor2\Jobs\{MariaDbJobQueue,MariaDbOutbox,OutboxDeliveryHandler,OutboxDispatchScheduler};
assertSameValue(true,class_exists(MariaDbOutbox::class)&&class_exists(OutboxDeliveryHandler::class)&&class_exists(OutboxDispatchScheduler::class),'INTENTIONAL_RED: public transactional outbox scheduling and delivery handler exist');
mysqli_report(MYSQLI_REPORT_ERROR|MYSQLI_REPORT_STRICT);$host=getenv('FMONITOR_TEST_DB_HOST')?:'127.0.0.1';$port=(int)(getenv('FMONITOR_TEST_DB_PORT')?:23306);$user=getenv('FMONITOR_TEST_DB_ADMIN_USER')?:'root';$password=getenv('FMONITOR_TEST_DB_ADMIN_PASSWORD')?:'fmonitor2_test_root_local';$name='t_outbox_'.bin2hex(random_bytes(5));$admin=new mysqli($host,$user,$password,'',$port);$admin->query("CREATE DATABASE `{$name}` DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");$db=new mysqli($host,$user,$password,$name,$port);$other=new mysqli($host,$user,$password,$name,$port);$p='outbox_';
try{JobsSchemaMigration::apply($db,$p);$db->query('CREATE TABLE domain_facts(id INT PRIMARY KEY,value VARCHAR(40))ENGINE=InnoDB');$createdAt='2026-09-09T07:58:00.000000Z';$outbox=new MariaDbOutbox($db,$p,static fn():string=>$createdAt);$otherOutbox=new MariaDbOutbox($other,$p,static fn():string=>'2026-09-09T09:59:00.000000Z');$queue=new MariaDbJobQueue($other,$p,static fn():string=>'2026-09-09T07:59:00.000000Z',static fn():string=>str_repeat('e',64),['outbox.dispatch'=>[1]]);$sweep=new OutboxDispatchScheduler($otherOutbox,$queue);$intent=['eventId'=>'event-0001','channel'=>'email','template'=>'approved-template-v1','version'=>1,'data'=>['objectId'=>7]];
    $db->begin_transaction();$db->query("INSERT INTO domain_facts VALUES(1,'pending')");$outbox->append($intent);assertSameValue([0,0],[(int)$other->query('SELECT COUNT(*)n FROM domain_facts')->fetch_assoc()['n'],(int)$other->query("SELECT COUNT(*)n FROM `{$p}fm2_outbox_intents`")->fetch_assoc()['n']],'uncommitted fact and intent invisible together');assertSameValue(0,$sweep->enqueuePending()['enqueued'],'separate post-commit sweep cannot see uncommitted intent');assertSameValue(0,(int)$other->query("SELECT COUNT(*)n FROM `{$p}fm2_jobs`")->fetch_assoc()['n'],'uncommitted intent creates no dispatch job');$db->rollback();assertSameValue([0,0],[(int)$other->query('SELECT COUNT(*)n FROM domain_facts')->fetch_assoc()['n'],(int)$other->query("SELECT COUNT(*)n FROM `{$p}fm2_outbox_intents`")->fetch_assoc()['n']],'rollback publishes neither');
    $db->begin_transaction();$db->query("INSERT INTO domain_facts VALUES(1,'committed')");$created=$outbox->append($intent);$db->commit();assertSameValue([1,1],[(int)$other->query('SELECT COUNT(*)n FROM domain_facts')->fetch_assoc()['n'],(int)$other->query("SELECT COUNT(*)n FROM `{$p}fm2_outbox_intents`")->fetch_assoc()['n']],'commit exposes fact and intent');$db->begin_transaction();$replayed=$outbox->append($intent);$db->commit();assertSameValue(['replayed',$created['intentId']],[$replayed['status'],$replayed['intentId']],'exact intent replay returns same identity');$conflictBefore=$db->query("SELECT * FROM `{$p}fm2_outbox_intents` ORDER BY intent_id")->fetch_all(MYSQLI_ASSOC);$db->begin_transaction();$conflict=$outbox->append(array_replace($intent,['data'=>['objectId'=>8]]));$db->commit();assertSameValue('conflict',$conflict['status'],'same event/channel different fingerprint conflicts');assertSameValue($conflictBefore,$db->query("SELECT * FROM `{$p}fm2_outbox_intents` ORDER BY intent_id")->fetch_all(MYSQLI_ASSOC),'intent conflict zero mutation');
    $db->begin_transaction();try{$outbox->append(array_replace($intent,['eventId'=>'event-secret','data'=>['password'=>'forbidden']]));throw new TestFailure('secret payload accepted');}catch(InvalidArgumentException){$db->rollback();}assertSameValue(1,(int)$db->query("SELECT COUNT(*)n FROM `{$p}fm2_outbox_intents`")->fetch_assoc()['n'],'secret rejection adds no intent');
    $scheduled=$sweep->enqueuePending();assertSameValue(1,$scheduled['enqueued'],'committed intent gets one generic dispatch job');$jobBefore=$other->query("SELECT available_at_utc,fingerprint FROM `{$p}fm2_jobs` WHERE job_type='outbox.dispatch'")->fetch_assoc();assertSameValue($createdAt,$jobBefore['available_at_utc'],'dispatch availability is immutable intent creation instant');assertSameValue(0,$sweep->enqueuePending()['enqueued'],'repeat sweep duplicates no dispatch job');assertSameValue($jobBefore,$other->query("SELECT available_at_utc,fingerprint FROM `{$p}fm2_jobs` WHERE job_type='outbox.dispatch'")->fetch_assoc(),'sweep wall clock cannot alter dispatch fingerprint/time');$claimed=$queue->claim(['workerId'=>'outbox-worker','batch'=>1])[0];assertSameValue(['outbox.dispatch',$created['intentId']],[$claimed['jobType'],$claimed['payload']['intentId']],'generic queue owns exact outbox dispatch work');$transportSecret='OUTBOX-TRANSPORT-SECRET-731';$calls=[];$transport=static function(array$message)use(&$calls,$transportSecret,$db):array{assertSameValue(0,(int)$db->query('SELECT @@in_transaction')->fetch_column(),'transport callback runs outside DB transaction');$calls[]=$message;return['status'=>'ambiguous_retryable','failureCode'=>'TRANSPORT_TIMEOUT','providerReference'=>'opaque-ref','diagnostic'=>$transportSecret];};$handler=new OutboxDeliveryHandler($outbox,$transport,static fn():string=>'2026-09-09T08:00:00.000000Z');$db->begin_transaction();$attemptsBefore=(int)$db->query("SELECT COUNT(*)n FROM `{$p}fm2_outbox_attempt_events`")->fetch_assoc()['n'];try{$handler->handle($claimed);throw new TestFailure('ambient transaction delivery accepted');}catch(LogicException$e){assertSameValue('AMBIENT_TRANSACTION',$e->getMessage(),'ambient transaction fails explicitly');}$db->rollback();assertSameValue([0,$attemptsBefore], [count($calls),(int)$db->query("SELECT COUNT(*)n FROM `{$p}fm2_outbox_attempt_events`")->fetch_assoc()['n']], 'ambient transaction invokes no transport and records no attempt');$attempt1=$handler->handle($claimed);$attempt2=$handler->handle(array_replace($claimed,['attempt'=>2]));assertSameValue(['ambiguous_retryable','ambiguous_retryable'],[$attempt1['status'],$attempt2['status']],'lost provider response remains explicit and retries intent alone');assertSameValue(2,count($calls),'network called only by generic post-commit job handler attempts');assertSameValue($calls[0]['idempotencyReference'],$calls[1]['idempotencyReference'],'provider retry keeps stable intent reference');assertSameValue('committed',$other->query('SELECT value FROM domain_facts WHERE id=1')->fetch_column(),'delivery ambiguity does not repeat domain command');assertSameValue(2,(int)$db->query("SELECT COUNT(*)n FROM `{$p}fm2_outbox_attempt_events`")->fetch_assoc()['n'],'both ambiguous attempts are append-only');$safe=json_encode([$attempt1,$attempt2,$db->query("SELECT * FROM `{$p}fm2_outbox_attempt_events`")->fetch_all(MYSQLI_ASSOC)],JSON_THROW_ON_ERROR);assertSameValue(false,str_contains($safe,$transportSecret),'transport diagnostic secret absent from outputs and persisted attempts');
    $encoded=json_encode($db->query("SELECT * FROM `{$p}fm2_outbox_intents`")->fetch_all(MYSQLI_ASSOC),JSON_THROW_ON_ERROR);foreach(['password','secret','authorization']as$forbidden)assertSameValue(false,str_contains(strtolower($encoded),$forbidden),'outbox persists no credential fields');echo"PASS: DURABLE-BACKGROUND-JOBS-001 transactional outbox\n";
}finally{$other->close();$db->close();$admin->query("DROP DATABASE IF EXISTS `{$name}`");$admin->close();}
